export const retiredSuccessorGeneratorSource = "import assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync, lstatSync, readFileSync, readdirSync, writeFileSync } from \"node:fs\";\nimport { mkdir } from \"node:fs/promises\";\nimport { join, relative } from \"node:path\";\nimport { gzipSync } from \"node:zlib\";\nimport { Database } from \"bun:sqlite\";\n\nconst root = import.meta.dir;\nconst output = join(root, \"capture4\");\nconst input = process.argv[2];\nassert.equal(typeof input, \"string\");\nconst inputBytes = readFileSync(input);\nconst hash = (value: string | Uint8Array) => createHash(\"sha256\").update(value).digest(\"hex\");\nconst inputSha256 = \"209e39cdccfaec8a198832b1004b6f1d0e250afc47fac576b2acfdfbcabeb7a8\";\nassert.equal(hash(inputBytes), inputSha256);\nassert.equal(Bun.version, \"1.3.14\");\nassert.equal(lstatSync(root).mode & 0o777, 0o700);\nassert.equal(existsSync(output), false, \"Never overwrite or restamp an archived capture.\");\nconst sourceDefinitions = {\n  41: { sourceCommit: \"576ccd76a6742cd62759ab6176a6a41844846daa\", sourceTree: \"a410268ccca4f5f6096a97b63d06652153d196be\",\n    stateStoreSha256: \"7aedcd4d6b4ad2e42ac3583af29d80fa280bf4f1546516df4da490ef54577d14\",\n    sourceManifestSha256: \"daf90e9b10e7f93e40d6f390f5f4eb0b42a7cd5d08832daa58e0eb74ff3dc2d4\" },\n  42: { sourceCommit: \"86466e289ffb7d836c6c3712f8bb8f0e453d5eb1\", sourceTree: \"c829453243d8cdcca1c5e9c6d800721532fb3fe6\",\n    stateStoreSha256: \"a0abae97836485c67b05235693883f39dcaa141c6da97a8e5db5e60d036eb45f\",\n    sourceManifestSha256: \"294b127d5c930f791a97e06984db1b9f547aea08f3d3d4d9edcb694935f85fd7\" },\n} as const;\nconst dependencies = { \"@hraness/oh\": \"0.2.7\", \"@openai/codex\": \"0.153.2\", convex: \"1.45.0\", effect: \"3.22.1\", zod: \"4.4.3\" };\nconst snapshot = (path: string) => {\n  // Query-only holder permits SQLite's empty WAL/SHM coordination for an\n  // unchanged archived WAL-mode image, without rewriting its header.\n  const db = new Database(path, { create: false, strict: true });\n  db.exec(\"PRAGMA query_only=ON\");\n  try {\n    const schema = db.query(\"SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name\").all();\n    const tables = db.query(\"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name\").all() as { name: string }[];\n    assert.ok(tables.length <= 256);\n    const rows: Record<string, unknown[]> = {};\n    for (const { name } of tables) {\n      assert.match(name, /^[a-zA-Z0-9_]+$/);\n      rows[name] = db.query(`SELECT * FROM \"${name}\"`).all().sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));\n      assert.ok(rows[name].length <= 4096);\n    }\n    const result = { userVersion: db.query(\"PRAGMA user_version\").get(), schema, rows,\n      foreignKeyCheck: db.query(\"PRAGMA foreign_key_check\").all(), inspectionChanges: db.query(\"SELECT total_changes() AS count\").get() };\n    assert.deepEqual(result.foreignKeyCheck, []);\n    assert.deepEqual(result.inspectionChanges, { count: 0 });\n    assert.ok(Buffer.byteLength(JSON.stringify(result)) < 8 * 1024 * 1024);\n    return result;\n  } finally { db.close(false); }\n};\nawait mkdir(output, { mode: 0o700 });\nconst generatorSource = readFileSync(import.meta.path, \"utf8\");\nconst summaries = [];\nfor (const version of [41, 42] as const) {\n  const sourceRoot = join(root, `canonical${version}`);\n  const definition = sourceDefinitions[version];\n  const sourceHashes = { \"src/storage/state-store.ts\": definition.stateStoreSha256,\n    \"package.json\": \"1ddf6d63c7f02778eeea54f273863dfcece8ae4c2fbbee291f76f2084e9d28b3\",\n    \"bun.lock\": \"cf06ffbd2a9439846d94b85e06a992d73a4931570d336a7e23409f5427d2a032\" };\n  for (const [path, expected] of Object.entries(sourceHashes)) assert.equal(hash(readFileSync(join(sourceRoot, path))), expected);\n  for (const [name, expected] of Object.entries(dependencies)) {\n    assert.equal(JSON.parse(readFileSync(join(sourceRoot, \"node_modules\", name, \"package.json\"), \"utf8\")).version, expected);\n  }\n  const sourceFiles: { path: string; sha256: string }[] = [];\n  function visit(directory: string) {\n    for (const entry of readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {\n      const path = join(directory, entry.name);\n      if (entry.isDirectory()) visit(path);\n      else if (entry.isFile()) sourceFiles.push({ path: relative(sourceRoot, path), sha256: hash(readFileSync(path)) });\n      else throw new Error(\"Unexpected archived source entry.\");\n    }\n  }\n  visit(join(sourceRoot, \"src\"));\n  assert.equal(sourceFiles.length, 277);\n  assert.equal(hash(JSON.stringify(sourceFiles)), definition.sourceManifestSha256);\n  const { StateStore } = await import(`./canonical${version}/src/storage/state-store`);\n  const { initializeStatePaths, resolveStatePaths } = await import(`./canonical${version}/src/storage/paths`);\n  const directory = join(output, `canonical${version}`);\n  await mkdir(directory, { mode: 0o700 });\n  const paths = resolveStatePaths({ rootDirectory: join(directory, \"state\") });\n  await initializeStatePaths(paths);\n  let predecessor: ReturnType<typeof snapshot> | null = null;\n  if (version === 41) {\n    // Exact canonical39 image, migrated only by the exact canonical41 producer.\n    writeFileSync(paths.database, inputBytes, { mode: 0o600, flag: \"wx\" });\n    predecessor = snapshot(paths.database);\n    assert.deepEqual(predecessor.userVersion, { user_version: 39 });\n  }\n  const fixedTime = version * 1000;\n  const store = new StateStore(paths, { now: () => fixedTime });\n  let retained: Record<string, unknown>;\n  if (version === 41) {\n    const sessions = store.listSessions(10);\n    const session = sessions.find((entry: { provider: string }) => entry.provider === \"devin\");\n    assert.ok(session);\n    const after = snapshot(paths.database);\n    for (const table of [\"session_runtime_profiles\", \"session_events\", \"mutation_attempts\", \"mutation_effect_evidence\", \"queue_entries\", \"queue_effect_evidence\"]) {\n      assert.deepEqual(after.rows[table], predecessor!.rows[table]);\n    }\n    const priorSessions = predecessor!.rows.sessions as { id: string; provider_v39: string; revision: number; state: string; updated_at: number }[];\n    for (const old of priorSessions) {\n      const current = (after.rows.sessions as { id: string }[]).find((row) => row.id === old.id);\n      // Canonical40 adoption legitimately contains the two unbound supported\n      // sessions. Retired Devin's row itself is preserved exactly.\n      assert.deepEqual(current, old.provider_v39 === \"devin\" ? old\n        : { ...old, state: \"recovery_required\", revision: old.revision + 1, updated_at: fixedTime });\n    }\n    assert.deepEqual((after.rows.migrations as { version: number }[]).filter((row) => row.version <= 39), predecessor!.rows.migrations);\n    retained = { session, profile: store.requireProfile(session.profileId),\n      runtime: store.latestSessionRuntimeProfile(session.id), queue: store.listQueue(session.id) };\n  } else {\n    const created = store.createProfile(\"Exact schema42 synthetic transcript history\");\n    const advanced = store.nextProfileGeneration(created.id);\n    const email = \"canonical42-transcript@example.com\";\n    assert.equal(store.setProfileState(advanced.id, advanced.processGeneration, \"signed_in\", { email, plan: \"Plus\" }), true);\n    const profile = store.requireProfile(advanced.id);\n    assert.equal(store.allocateNextUsageRevision(profile.id), 1);\n    const session = store.upsertProviderSession({ profileId: profile.id, provider: \"codex\",\n      providerThreadId: \"canonical42-synthetic-transcript\", providerAccountKey: \"v1:codex:\" + hash(email),\n      title: \"Synthetic pre-finalization transcript\", preset: \"high\", fastEnabled: false, state: \"idle\" });\n    const appliedMutationKey = \"43000000-0000-4000-8000-000000000001\";\n    const preparedMutationKey = \"43000000-0000-4000-8000-000000000002\";\n    const legacyUnsafeName = \"legacy\" + String.fromCodePoint(0x2028) + \"name.txt\";\n    const appliedMutation = store.prepareMutation({ kind: \"session.send\", authorityId: session.id,\n      authorityGeneration: profile.processGeneration, request: { message: \"already dispatched\" }, idempotencyKey: appliedMutationKey });\n    assert.equal(store.transitionMutation(appliedMutation.id, \"prepared\", \"effect_started\"), true);\n    assert.equal(store.transitionMutation(appliedMutation.id, \"effect_started\", \"applied\", { turnId: \"old-turn\" }), true);\n    store.prepareMutation({ kind: \"session.send\", authorityId: session.id, authorityGeneration: profile.processGeneration,\n      request: { message: \"not dispatched\", attachments: [{ byteLength: 4, digest: \"9\".repeat(64), mediaType: \"text/plain\", name: legacyUnsafeName }] },\n      idempotencyKey: preparedMutationKey });\n    const dispatching = store.enqueue(session.id, \"already dispatching\");\n    assert.equal(store.transitionQueue(dispatching.id, \"pending\", \"dispatching\"), true);\n    const pendingQueue = store.enqueue(session.id, \"still pending\");\n    const legacyAttachment = { byteLength: 4, canonicalMediaType: \"text/plain\", digest: \"8\".repeat(64), mediaType: \"text/plain\", name: legacyUnsafeName };\n    store.recordMessageAttachments({ sessionId: session.id, sourceId: pendingQueue.id, attachments: [legacyAttachment] });\n    assert.equal(store.messageAttachmentManifest(session.id, pendingQueue.id)[0]?.name, legacyUnsafeName);\n    const laterPendingQueue = store.enqueue(session.id, \"must not be blocked after upgrade\");\n    retained = { profile, session, appliedMutationKey, appliedMutation: store.readMutation(appliedMutationKey),\n      preparedMutationKey, preparedMutation: store.readMutation(preparedMutationKey), legacyAttachment,\n      dispatchingQueue: store.requireQueue(dispatching.id), pendingQueue, laterPendingQueue };\n  }\n  const finalSnapshot = snapshot(paths.database);\n  assert.deepEqual(finalSnapshot.userVersion, { user_version: version });\n  store.close();\n  const reopened = new StateStore(paths, { now: () => fixedTime });\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  reopened.close();\n  const checkpoint = new Database(paths.database, { create: false, strict: true });\n  const checkpointResult = checkpoint.query(\"PRAGMA wal_checkpoint(TRUNCATE)\").get();\n  checkpoint.close(false);\n  assert.equal((checkpointResult as { busy: number }).busy, 0);\n  const beforeReadonly = hash(readFileSync(paths.database));\n  const readonly = new StateStore(paths, { readonly: true });\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  readonly.close();\n  const bytes = readFileSync(paths.database);\n  assert.equal(hash(bytes), beforeReadonly);\n  const metadata = { ...definition, schemaVersion: version, sourceHashes, generatorSha256: hash(generatorSource),\n    bunVersion: Bun.version, dependencies, fixedTime, predecessorDatabaseSha256: version === 41 ? inputSha256 : null,\n    predecessorSourceCommit: version === 41 ? \"5f2735191640037c86d9949bc1d7f04b2ef09ffe\" : null,\n    provenance: { syntheticControlPlaneOnly: true, archivedPublicApisOnly: true, nativeProviderEffects: 0,\n      noNativeCustodyProof: true, rawSqlRowOrSchemaWrites: false, randomizedIdentifiers: true,\n      writableReopenUnchanged: true, readonlyReopenUnchanged: true, readonlyDatabaseHashUnchanged: true,\n      source42ReleaseOrCurrentMergedAdmissionClaim: false },\n    databaseSha256: hash(bytes), databaseBytes: bytes.length, checkpointResult, retained, snapshot: finalSnapshot };\n  const text = JSON.stringify(metadata);\n  for (const forbidden of [root, \"/Users/\", \"/private/\", \"/tmp/\", \"/home/\", \"/Volumes/\"]) {\n    assert.equal(text.includes(forbidden), false);\n    assert.equal(bytes.includes(Buffer.from(forbidden)), false);\n  }\n  writeFileSync(join(directory, \"state.sqlite.gz\"), gzipSync(bytes), { mode: 0o600, flag: \"wx\" });\n  writeFileSync(join(directory, \"fixture.json\"), JSON.stringify(metadata, null, 2) + \"\\n\", { mode: 0o600, flag: \"wx\" });\n  writeFileSync(join(directory, \"source-manifest.json\"), JSON.stringify(sourceFiles, null, 2) + \"\\n\", { mode: 0o600, flag: \"wx\" });\n  for (const [path, expected] of Object.entries(sourceHashes)) assert.equal(hash(readFileSync(join(sourceRoot, path))), expected);\n  summaries.push({ version, sourceCommit: definition.sourceCommit, databaseSha256: hash(bytes), databaseBytes: bytes.length,\n    sessions: finalSnapshot.rows.sessions.length, queues: finalSnapshot.rows.queue_entries.length, archivedReopensUnchanged: true });\n}\nassert.equal(hash(readFileSync(input)), inputSha256);\nconsole.log(JSON.stringify({ generatorSha256: hash(generatorSource), summaries }));\n";
