export const retiredSuccessorDatabaseBytes = (version: 41 | 42): Uint8Array => {
  const fixture = retiredSuccessorFixtures[version];
  if (createHash("sha256").update(retiredSuccessorGeneratorSource).digest("hex") !== fixture.generatorSha256) {
    throw new Error("RETIRED_SUCCESSOR_GENERATOR_MISMATCH");
  }
  const maximum = retiredSuccessorFixtures[41].databaseBytes + retiredSuccessorFixtures[42].databaseBytes;
  const all = gunzipSync(Buffer.from(gzipBase64, "base64"), { maxOutputLength: maximum });
  if (all.length !== maximum) throw new Error("RETIRED_SUCCESSOR_CAPTURE_MISMATCH");
  let offset = 0;
  for (const key of [41, 42] as const) {
    const entry = retiredSuccessorFixtures[key];
    const bytes = all.subarray(offset, offset + entry.databaseBytes);
    if (createHash("sha256").update(bytes).digest("hex") !== entry.databaseSha256) throw new Error("RETIRED_SUCCESSOR_CAPTURE_MISMATCH");
    offset += entry.databaseBytes;
  }
  const start = version === 41 ? 0 : retiredSuccessorFixtures[41].databaseBytes;
  return new Uint8Array(all.subarray(start, start + fixture.databaseBytes));
};
